contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will try arbitrary amounts and simulate a Collect call from this contract.
    // The test function is payable so it can deposit funds into c first.
    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Ensure c is initialized with a MinSum of 0 so that Collect eligibility depends only on balances
        // Use the public setter before Initialized() is called in C. It's allowed since c is fresh.
        c.SetMinSum(0); if (__ESBMC_reverted()) return;

        // Deposit depositAmount into c from this contract
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Read balance before Collect
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // Now we attempt Collect. To force the internal external-call to fail, we make this contract revert on receiving Ether.
        // We'll call Collect and catch whether it reverted.
        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General rule asserted:
        // If the Collect call reverted, then c's stored balance for this caller and c's Ether balance are unchanged.
        assert(!reverted || (afterBal == beforeBal && afterCbal == beforeCbal));
    }

    // Make the contract revert when it receives Ether so that c's attempt to send Ether to msg.sender fails.
    receive() external payable {
        revert("force fail");
    }
}

